; ---------------------------------------------------------------------------
; CYCLE BUDGET PROBE (v31 + tunable burn) -- generated by tools/gen_reverb.py, do not hand-edit
;
; Four series allpasses into a four-line FDN with a 4x4 Hadamard, one-pole
; damping inside the feedback path, and interpolated modulation on two lines.
;
; All buffers are relative to the per-instance base at x:(x:>$213), so two
; tracks running this effect do not write through each other. An FX2 instance is
; given 0x4000 words:
;   lines      base+0x0000 .. base+0x1fff   2048 words each
;              taps 1567 1249 977 733  (36 28 22 17 ms)
;   allpasses  base+0x2000 .. base+0x2fff   1024 words each
;              taps 907 673 487 331  (21 15 11 8 ms)
;   pre-delay  base+0x3000 .. base+0x37ff   2048 words (46 ms)
;   total      0x3800 of the 0x4000 an FX2 instance is given
;
; The allpasses are long on purpose. Four lines at ~50 ms is only ~80 echoes a
; second, which on its own reads as a stutter rather than a wash; the density
; has to come from diffusion, so the allpasses run 9-24 ms instead of the 3-8 ms
; they were when the whole engine had to fit in 6K.
;
; State (all in the per-instance r7 block, not absolute Y):
;   r7+$83        write phase (persistent, masked on load as well as save)
;   r7+$83        the ONE persistent word: tank / allpass / pre-delay phase
;   base+0x3800   LFO phase and 4 damping states, loaded per block
;   r7+$71..$78   this instance's base, and the bases derived from it
;   r7+$55..$66   per-sample scratch
;
; Parameters:
;   p0 TIME -> feedback, 0.875 .. 0.999
;   p1 DAMP -> one-pole coefficient. s += c*(d-s), so a LARGE c keeps highs.
;              DAMP up lowers c: 0 = bright, 127 = dark.
;   p5 MIX  -> wet gain
; ---------------------------------------------------------------------------

init:
; No loop, and nothing reset that has to survive.
;
; Reading X:$213 is only valid HERE. Stash the base where process can
; find it: absolute Y, but at an address unique to this instance.
        move    x:>$213,r4
        move    r7,a
        asr     #$8,a,a                 ; r7 >> 8; also fills the AGU slot
        move    x:(r4),x0               ; this instance's buffer base
        move    #>$735,y0
        add     y0,a
        move    a,r5
        move    #>$ffffff,m5
        move    #>$ffffff,m0            ; both fill the AGU slot
        move    x0,y:(r5)
        move    #>$ffffff,m1
        move    #>$ffffff,m2
        move    #>$ffffff,m3
        move    #>$ffffff,m4
        rts

proc:
; ---- this instance's buffer base, derived from r7 -----------------------
; The host advances X:$213 (buffer bases) and X:0x20a (state blocks)
; together, one per effect, so the table index is recoverable from r7 alone:
;
;     n = (r7 - 0x6000) >> 8        base = x:(0x255 + n)
;
; Reading X:$213 directly only works in init, because the dispatcher
; advances it before calling process. Deriving it from r7 works ANYWHERE and
; needs nothing to survive between calls -- which matters, because parts of the
; r7 block are demonstrably volatile (r7+$50 does not persist).
        move    r7,a
        asr     #$8,a,a
        move    #>$735,y0
        add     y0,a
        move    a,r5
        move    #>$ffffff,m0            ; audio is read and written via r0
        move    #>$7ff,m1     ; both fill the AGU slot
        move    y:(r5),x0               ; the base init stashed for us
        move    x0,x:(r7+$71)

; ---- every buffer base, derived once per block --------------------------
        move    #>$2000,a
        add     x0,a
        move    a,x:(r7+$72)
        move    #>$2400,a
        add     x0,a
        move    a,x:(r7+$73)
        move    #>$2800,a
        add     x0,a
        move    a,x:(r7+$74)
        move    #>$2c00,a
        add     x0,a
        move    a,x:(r7+$75)
        move    #>$800,a
        add     x0,a
        move    a,x:(r7+$76)
        move    #>$1000,a
        add     x0,a
        move    a,x:(r7+$77)
        move    #>$3000,a
        add     x0,a
        move    a,x:(r7+$78)

; ---- per-block: load the state that cannot be derived -------------------
; The LFO phase and the four one-pole states are the only things that must
; survive between calls and cannot be recomputed. They live in the instance's
; own Y region, so they are per-instance, and touching them once per block costs
; nothing per sample.
        move    #>$3800,a
        add     x0,a
        move    a,x:(r7+$7f)            ; keep the address for the save
        move    a,r5
        move    #>$ffffff,m5            ; linear for the walk
        move    x:(r7+$71),x0           ; restore x0 = base; fills the AGU slot
        move    y:(r5)+,a
        move    a,x:(r7+$7e)
        move    y:(r5)+,a
        move    a,x:(r7+$7a)
        move    y:(r5)+,a
        move    a,x:(r7+$7b)
        move    y:(r5)+,a
        move    a,x:(r7+$7c)
        move    y:(r5)+,a
        move    a,x:(r7+$7d)

; ---- rebuild the four delay pointers from the saved phase ----------------
        move    x:(r7+$83),a
        move    #>$7ff,x0
        and     x0,a                    ; mask on LOAD: the phase may be garbage
        move    x:(r7+$71),x0
        add     x0,a                    ; base + LINE_OFF(0x0)
        move    a,r1                    ; line 0
        move    #>$800,x0
        add     x0,a
        move    a,r2                    ; line 1
        add     x0,a
        move    a,r3                    ; line 2
        add     x0,a
        move    a,r4                    ; line 3
        move    #>$7ff,m1
        move    #>$7ff,m2
        move    #>$7ff,m3
        move    #>$7ff,m4

; ---- SIZE: scale all four tap lengths -----------------------------------
; Each tap is held as a fraction of LINE_LEN (tap << 11), multiplied by a factor
; f = 0.125 .. 0.992, and shifted back to an integer. The nominal taps are the
; MAXIMUM, so SIZE only ever shrinks the space: 1567 samples down to
; about 195, i.e. 36 ms down to 4 ms on the longest line.
; Setup only -- this runs once per block, not per sample.
        move    x:(r6+$2),x0
        move    #>$700000,y1
        mpy     x0,y1,a                 ; * 0.875 FIRST -- $100000 + $7f0000 is
        move    #>$100000,x0            ; $8f0000, which reads as NEGATIVE, and
        add     x0,a                    ; a negative f flips every tap
        move    a,x1                    ; f = 0.125 .. 0.995
        move    #>$30f800,x0            ; 1567 as a fraction of 2048
        mpy     x0,x1,a
        asr     #$b,a,a                 ; back to an integer tap
        neg     a
        move    a,n1                    ; -tap, line 0 reads y:(r1+n1)
        move    #>$270800,x0            ; 1249 as a fraction of 2048
        mpy     x0,x1,a
        asr     #$b,a,a                 ; back to an integer tap
        move    #>$800,b
        sub     a,b                     ; 2048 - tap, for the modulated read
        move    b,x:(r7+$6a)
        move    #>$1e8800,x0            ; 977 as a fraction of 2048
        mpy     x0,x1,a
        asr     #$b,a,a                 ; back to an integer tap
        move    #>$800,b
        sub     a,b                     ; 2048 - tap, for the modulated read
        move    b,x:(r7+$6b)
        move    #>$16e800,x0            ; 733 as a fraction of 2048
        mpy     x0,x1,a
        asr     #$b,a,a                 ; back to an integer tap
        neg     a
        move    a,n4                    ; -tap, line 3 reads y:(r4+n4)
        move    #>$7ff,m5           ; pre-delay modulo. Harmless to the
                                        ; diffuser: it only ever does plain
                                        ; y:(r5), never a post-increment, and
                                        ; modulo affects updates, not reads.

; ---- feedback gain from TIME --------------------------------------------
; p0 arrives as value<<16. The 4x4 Hadamard has row norm 2, so folding the half
; into the gain makes the matrix orthonormal and the loop gain equal to g.
;
; g now spans 0.935..0.9995, not 0.875..0.999. Decay is g^n where n is passes,
; so RT60 scales with the loop time -- and fitting a real 16K allocation halved
; the mean tap from ~51 ms to ~26 ms, which halved every decay time and made
; TIME feel like it had stopped doing anything. g_new = g_old^0.5 restores the
; old RT60 range over the same knob travel.
        move    x:(r6),x0
        move    #>$043000,y1
        mpy     x0,y1,a
        move    #>$3bd000,x0
        add     x0,a
        move    a,x:(r7+$5e)

; ---- HI: high cut, as an EQ rather than a damping amount -----------------
; The one-pole is s += c*(d-s), so a LARGE c tracks the input and keeps highs.
; HI reads as an EQ control, so it has to run the other way from the old DAMP:
; HI=0 gives c=0.125 (dark), HI=127 gives c~0.99 (bright).
        move    x:(r6+$1),x0
        move    #>$700000,y1
        mpy     x0,y1,a
        move    #>$100000,x0
        add     x0,a
        move    a,x:(r7+$5f)

; ---- MIX -----------------------------------------------------------------
        move    x:(r6+$5),x0
        move    x0,x:(r7+$60)

; ---- MOD: modulation depth, scales the LFO triangle ---------------------
        move    x:(r6+$4),x0
        move    x0,x:(r7+$68)

; ---- WIDTH: 0 = mono, 127 = full stereo ---------------------------------
        move    x:(r6+$b),x0
        move    x0,x:(r7+$6c)

; ---- RATE: LFO increment, ~0.34 Hz .. ~3 Hz -----------------------------
; 8x what it would be per sample, because the LFO is stepped once per block.
        move    x:(r6+$d),a
        asr     #$b,a,a
        move    #>$200,x0
        add     x0,a
        move    a,x:(r7+$6f)

; ---- PRE: pre-delay in samples, 0 .. 2032 (46 ms) -----------------------
; v * 16. The scale MUST keep this below PRE_LEN (2048): the read is
; y:(r5+n5) under m5 modulo, and a modulo offset larger than the buffer is
; undefined on the DSP56300. It does not wrap -- the read returns nothing, the
; tank gets no input, and the reverb goes completely silent.
        move    x:(r6+$e),a
        asr     #$c,a,a
        move    a,x:(r7+$69)
        move    #>$1,x0                 ; the read happens BEFORE the write, so
        add     x0,a                    ; the offset is -(PRE+1): at PRE=0 that
        neg     a                       ; is one sample, not a whole buffer of
        move    a,n5                    ; staleness
        move    x:(r7+$83),a            ; the same counter again
        move    #>$7ff,x0
        and     x0,a
        move    x:(r7+$78),x0
        add     x0,a
        move    a,x:(r7+$70)            ; NOT $6d: the width matrix uses that

; ---- LFO: one triangle and its inverse ----------------------------------
        move    x:(r7+$7e),a               ; persistent phase, [0,$7fffff]
        move    x:(r7+$6f),x0           ; increment, from RATE
        add     x0,a
        move    #>$7fffff,x0
        and     x0,a                    ; wrap; A1 is right even if A2 carried
        move    a1,x0                   ; extract without saturating on A2
        move    x0,x:(r7+$7e)
        move    x0,a                    ; clean copy, A2 = 0
        move    #>$400000,x0
        sub     x0,a
        abs     a                       ; triangle T, 0 .. $400000
        move    a,x0
        move    x:(r7+$68),y1           ; MOD depth
        mpy     x0,y1,a                 ; scaled triangle
        move    a1,x0
        move    x0,x:(r7+$66)           ; stash for the inverse
        move    a1,x1                   ; T
        asl     #$5,a,a
        move    a2,x0
        move    x0,x:(r7+$61)     ; line 1: integer offset, 0..8
        move    x1,a                    ; T again, A2 = 0 because T is positive
        move    #>$07ffff,x0
        and     x0,a
        asl     #$4,a,a                 ; fraction, at most $7ffff0 -> positive
        move    a,x0
        move    x0,x:(r7+$62)
        move    #>$400000,a
        move    x:(r7+$66),x0
        sub     x0,a                    ; inverse triangle
        move    a1,x1                   ; T
        asl     #$5,a,a
        move    a2,x0
        move    x0,x:(r7+$63)     ; line 2: integer offset, 0..8
        move    x1,a                    ; T again, A2 = 0 because T is positive
        move    #>$07ffff,x0
        and     x0,a
        asl     #$4,a,a                 ; fraction, at most $7ffff0 -> positive
        move    a,x0
        move    x0,x:(r7+$64)

        do      n7,>rvend

; ---- input: mono sum -----------------------------------------------------
        move    #>$1,n0
        move    x:(r0),a
        move    x:(r0+n0),x0
        add     x0,a
        asr     #$1,a,a
        move    a,x:(r7+$5b)
        move    r1,a                    ; the allpass phase IS the tank phase:
        move    #>$3ff,x0       ; both advance by 1 a sample, and the
        and     x0,a                    ; line base is aligned, so r1 masked is it
        move    a,x:(r7+$79)

; ---- pre-delay ----------------------------------------------------------
; r5 with m5 modulo and a plain post-increment -- the same shape as the tank
; lines, which are proven safe. The earlier version computed the addresses
; arithmetically like the diffuser does, which cost 28 instructions a sample;
; that is only necessary when r5 and n5 are RECOMPUTED inside the loop, and
; here they are set once per block.
        move    x:(r7+$70),r5           ; restore: the allpasses clobber r5
        move    x:(r7+$5b),a            ; input, and fills the AGU slot
        move    #>$1,n0
        move    y:(r5+n5),b             ; delayed
        move    a,y:(r5)+               ; write, and advance
        move    r5,x:(r7+$70)
        move    b,x:(r7+$5b)            ; delayed input -> the diffuser

; -- allpass 0: base+0x2000, tap 907 (20.6 ms) --
        move    x:(r7+$79),a
        move    #>117,x0
        add     x0,a
        move    #>$3ff,x0
        and     x0,a                    ; (phase - tap) mod 1024
        move    x:(r7+$72),x0
        add     x0,a
        move    a,r5
        move    #>$400000,y0            ; coefficient, and fills the AGU slot
        move    y:(r5),b                ; d
        move    b,x0
        mpy     x0,y0,a
        move    x:(r7+$5b),x0
        add     x0,a                    ; v = x + g*d
        move    a,x:(r7+$5c)
        move    a,x1
        mpy     x1,y0,a
        sub     a,b                     ; out = d - g*v
        move    b,x:(r7+$5b)
        move    x:(r7+$79),a               ; write v at base + phase
        move    x:(r7+$72),x0
        add     x0,a
        move    a,r5
        move    x:(r7+$5c),a            ; reload v, fills the AGU slot
        move    a,y:(r5)

; -- allpass 1: base+0x2400, tap 673 (15.3 ms) --
        move    x:(r7+$79),a
        move    #>351,x0
        add     x0,a
        move    #>$3ff,x0
        and     x0,a                    ; (phase - tap) mod 1024
        move    x:(r7+$73),x0
        add     x0,a
        move    a,r5
        move    #>$400000,y0            ; coefficient, and fills the AGU slot
        move    y:(r5),b                ; d
        move    b,x0
        mpy     x0,y0,a
        move    x:(r7+$5b),x0
        add     x0,a                    ; v = x + g*d
        move    a,x:(r7+$5c)
        move    a,x1
        mpy     x1,y0,a
        sub     a,b                     ; out = d - g*v
        move    b,x:(r7+$5b)
        move    x:(r7+$79),a               ; write v at base + phase
        move    x:(r7+$73),x0
        add     x0,a
        move    a,r5
        move    x:(r7+$5c),a            ; reload v, fills the AGU slot
        move    a,y:(r5)

; -- allpass 2: base+0x2800, tap 487 (11.0 ms) --
        move    x:(r7+$79),a
        move    #>537,x0
        add     x0,a
        move    #>$3ff,x0
        and     x0,a                    ; (phase - tap) mod 1024
        move    x:(r7+$74),x0
        add     x0,a
        move    a,r5
        move    #>$400000,y0            ; coefficient, and fills the AGU slot
        move    y:(r5),b                ; d
        move    b,x0
        mpy     x0,y0,a
        move    x:(r7+$5b),x0
        add     x0,a                    ; v = x + g*d
        move    a,x:(r7+$5c)
        move    a,x1
        mpy     x1,y0,a
        sub     a,b                     ; out = d - g*v
        move    b,x:(r7+$5b)
        move    x:(r7+$79),a               ; write v at base + phase
        move    x:(r7+$74),x0
        add     x0,a
        move    a,r5
        move    x:(r7+$5c),a            ; reload v, fills the AGU slot
        move    a,y:(r5)

; -- allpass 3: base+0x2c00, tap 331 (7.5 ms) --
        move    x:(r7+$79),a
        move    #>693,x0
        add     x0,a
        move    #>$3ff,x0
        and     x0,a                    ; (phase - tap) mod 1024
        move    x:(r7+$75),x0
        add     x0,a
        move    a,r5
        move    #>$400000,y0            ; coefficient, and fills the AGU slot
        move    y:(r5),b                ; d
        move    b,x0
        mpy     x0,y0,a
        move    x:(r7+$5b),x0
        add     x0,a                    ; v = x + g*d
        move    a,x:(r7+$5c)
        move    a,x1
        mpy     x1,y0,a
        sub     a,b                     ; out = d - g*v
        move    b,x:(r7+$5b)
        move    x:(r7+$79),a               ; write v at base + phase
        move    x:(r7+$75),x0
        add     x0,a
        move    a,r5
        move    x:(r7+$5c),a            ; reload v, fills the AGU slot
        move    a,y:(r5)

        move    x:(r7+$5b),a
        move    a,x:(r7+$55)            ; diffused input -> tank
        asr     #$1,a,a
        move    a,x:(r7+$67)            ; and at half, for the other three lines

; ---- four taps, damped inside the feedback path -------------------------
        move    x:(r7+$5f),y0           ; damping coefficient, from DAMP
        move    y:(r1+n1),a         ; line 0, fixed tap 1567
        move    x:(r7+$7a),b
        sub     b,a
        move    a,x0
        mpy     x0,y0,a
        add     b,a
        move    a,x:(r7+$7a)
        move    a,x:(r7+$56)

; -- line 1 modulated: base+0x0800, tap 1249, interpolated --
        move    r1,b
        move    #>$7ff,x0
        and     x0,b                    ; shared write phase
        move    x:(r7+$61),x0
        sub     x0,b                    ; phase - offset
        move    x:(r7+$6a),x0    ; 2048 - tap, from SIZE
        add     x0,b
        move    #>$7ff,x0
        and     x0,b                    ; i0
        move    b,a
        add     x0,a
        and     x0,a                    ; i1 = (i0-1) mod 2048
        move    x:(r7+$76),x0
        add     x0,b
        add     x0,a
        move    a,x1
        move    b,r5
        move    x:(r7+$62),y1     ; fraction -- y1, NOT y0: y0 holds DAMP
        move    x1,a
        move    y:(r5),b                ; d0
        move    a,r5
        move    b,x:(r7+$65)
        move    b,x0                    ; both fill the AGU slot
        move    y:(r5),a                ; d1
        sub     x0,a
        move    a,x0
        mpy     x0,y1,a                 ; f*(d1-d0)
        move    x:(r7+$65),x0
        add     x0,a                    ; interpolated tap
        move    x:(r7+$7b),b
        sub     b,a
        move    a,x0
        mpy     x0,y0,a
        add     b,a
        move    a,x:(r7+$7b)
        move    a,x:(r7+$57)

; -- line 2 modulated: base+0x1000, tap 977, interpolated --
        move    r1,b
        move    #>$7ff,x0
        and     x0,b                    ; shared write phase
        move    x:(r7+$63),x0
        sub     x0,b                    ; phase - offset
        move    x:(r7+$6b),x0    ; 2048 - tap, from SIZE
        add     x0,b
        move    #>$7ff,x0
        and     x0,b                    ; i0
        move    b,a
        add     x0,a
        and     x0,a                    ; i1 = (i0-1) mod 2048
        move    x:(r7+$77),x0
        add     x0,b
        add     x0,a
        move    a,x1
        move    b,r5
        move    x:(r7+$64),y1     ; fraction -- y1, NOT y0: y0 holds DAMP
        move    x1,a
        move    y:(r5),b                ; d0
        move    a,r5
        move    b,x:(r7+$65)
        move    b,x0                    ; both fill the AGU slot
        move    y:(r5),a                ; d1
        sub     x0,a
        move    a,x0
        mpy     x0,y1,a                 ; f*(d1-d0)
        move    x:(r7+$65),x0
        add     x0,a                    ; interpolated tap
        move    x:(r7+$7c),b
        sub     b,a
        move    a,x0
        mpy     x0,y0,a
        add     b,a
        move    a,x:(r7+$7c)
        move    a,x:(r7+$58)

        move    y:(r4+n4),a         ; line 3, fixed tap 733
        move    x:(r7+$7d),b
        sub     b,a
        move    a,x0
        mpy     x0,y0,a
        add     b,a
        move    a,x:(r7+$7d)
        move    a,x:(r7+$59)

; ---- 4x4 Hadamard: adds and subtracts only ------------------------------
        move    x:(r7+$57),x0
        move    x:(r7+$56),a
        add     x0,a
        move    a,x:(r7+$5a)            ; u0 = d0+d1
        move    x:(r7+$56),a
        sub     x0,a
        move    a,x:(r7+$5b)            ; u1 = d0-d1
        move    x:(r7+$59),x0
        move    x:(r7+$58),a
        add     x0,a
        move    a,x:(r7+$5c)            ; u2 = d2+d3
        move    x:(r7+$58),a
        sub     x0,a
        move    a,x:(r7+$5d)            ; u3 = d2-d3

; ---- feedback and write back --------------------------------------------
        move    x:(r7+$5e),y0           ; g/2
        move    x:(r7+$5c),x0
        move    x:(r7+$5a),a
        add     x0,a
        move    a,x0
        mpy     x0,y0,a
        move    x:(r7+$55),x0           ; diffused input
        add     x0,a
        move    a,y:(r1)+

        move    x:(r7+$5d),x0
        move    x:(r7+$5b),a
        add     x0,a
        move    a,x0
        mpy     x0,y0,a
        move    x:(r7+$55),x0           ; diffused input
        sub     x0,a
        move    a,y:(r2)+

        move    x:(r7+$5c),x0
        move    x:(r7+$5a),a
        sub     x0,a
        move    a,x0
        mpy     x0,y0,a
        move    x:(r7+$67),x0           ; diffused input, half
        sub     x0,a
        move    a,y:(r3)+

        move    x:(r7+$5d),x0
        move    x:(r7+$5b),a
        sub     x0,a
        move    a,x0
        mpy     x0,y0,a
        move    x:(r7+$67),x0           ; diffused input, half
        add     x0,a
        move    a,y:(r4)+

; ---- wet added to dry, two tank taps per channel -------------------------
        move    x:(r7+$60),y1           ; wet gain
        move    x:(r7+$57),a            ; line 1, tap 1249
        move    x:(r7+$58),x0           ; line 2, tap 977
        add     x0,a
        asr     #$1,a,a
        move    a,x:(r7+$6d)            ; wet L
        move    x:(r7+$56),a            ; line 0, tap 1567
        move    x:(r7+$59),x0           ; line 3, tap 733
        add     x0,a
        asr     #$1,a,a
        move    a,x:(r7+$6e)            ; wet R

; ---- WIDTH: mid/side, then MIX, then onto the dry -----------------------
; M = (L+R)/2, S = (L-R)/2, out = M +/- w*S. w=0 collapses to mono, w=1 gives
; back exactly the two tap sums.
        move    x:(r7+$6d),a
        move    x:(r7+$6e),x0
        add     x0,a
        asr     #$1,a,a
        move    a,x:(r7+$65)            ; M
        move    x:(r7+$6d),a
        sub     x0,a
        asr     #$1,a,a
        move    a,x0
        move    x:(r7+$6c),y0           ; WIDTH
        mpy     x0,y0,a
        move    a,x:(r7+$66)            ; w*S
        move    x:(r7+$65),a
        move    x:(r7+$66),x0
        add     x0,a
        move    a,x0
        mpy     x0,y1,a                 ; * MIX
        move    x:(r0),x0
        add     x0,a
        move    a,x:(r0)                ; L in place
        move    x:(r7+$65),a
        move    x:(r7+$66),x0
        sub     x0,a
        move    a,x0
        mpy     x0,y1,a
        move    x:(r0+n0),x0
        add     x0,a
        move    a,x:(r0+n0)             ; R in place
        move    #>$2,n0
        move    (r0)+n0                 ; advance one stereo frame
rvend:


; ---- CYCLE BUDGET PROBE -- burn a knob-controlled number of cycles ------
; The whole "309-360 instructions per sample" ceiling came from v19 hanging at
; 360. But v20, which fixed it, ALSO fixed a SIZE sign overflow, a scratch-slot
; collision and a PRE=0 bug -- any of which could have been the real cause. The
; ceiling was never isolated, and everything since has been designed around it.
;
; So measure it. The spare page-1 knob (p3, shown as HP) adds
;
;     knob * 16 iterations of a 2-cycle loop, per proc call
;   = knob * 4 cycles per sample at 8 frames, 0 .. ~508
;
; Sweep it up until the audio dies. The budget for ONE instance is then about
; 298 + 4*knob instructions per sample.
;
; Two instances of this reverb would need ~596. If it survives past knob 74,
; cycles CANNOT be what makes two tracks crash, and the block-processing
; refactor -- while still worth doing for headroom -- would not fix it.
;
; +1 on the count because DO with a count of zero loops 65536 times.
        move    x:(r6+$3),a
        asr     #$10,a,a
        asl     #$4,a,a
        move    #>$1,x0
        add     x0,a
        move    a,x0
        do      x0,>burnend
        nop
burnend:
        nop

; ---- per-block: write the underivable state back -------------------------
        move    x:(r7+$7f),r5
        move    #>$ffffff,m5
        move    x:(r7+$7e),a               ; fills the AGU slot
        move    a,y:(r5)+
        move    x:(r7+$7a),a
        move    a,y:(r5)+
        move    x:(r7+$7b),a
        move    a,y:(r5)+
        move    x:(r7+$7c),a
        move    a,y:(r5)+
        move    x:(r7+$7d),a
        move    a,y:(r5)+

; ---- save the phase, restore the M registers ---------------------------
        move    r1,a
        move    #>$7ff,x0
        and     x0,a
        move    a,x:(r7+$83)
        move    #>$ffffff,m0
        move    #>$ffffff,m1
        move    #>$ffffff,m2
        move    #>$ffffff,m3
        move    #>$ffffff,m4
        move    #>$ffffff,m5
        rts
